from pathlib import Path
from PIL import Image
import numpy as np,json
from scipy.ndimage import map_coordinates
R=Path.cwd();P=R/'character/bill-east-idle-master-consistency-v1';a=json.loads((P/'source-baseline.json').read_text());source=np.array(Image.open(R/a['rows'][0]['path']).convert('RGBA'));yy,xx=np.indices(source.shape[:2]);v=source.astype(float)/255;prem=v.copy();prem[:,:,:3]*=prem[:,:,3:];e=np.where((yy>53)&(yy<121),np.sin(np.pi*np.clip((yy-53)/68,0,1))**2,0);side=np.tanh((xx-92)/8);rows=[]
for i in range(72):
 phase=(1-np.cos(2*np.pi*i/72))/2;dx=1.25*phase*e*side;dy=-.65*phase*e;b=np.stack([map_coordinates(prem[:,:,k],[yy-dy,xx-dx],order=1,mode='constant',cval=0) for k in range(4)],axis=-1);b[:,:,:3]=np.divide(b[:,:,:3],b[:,:,3:],out=np.zeros_like(b[:,:,:3]),where=b[:,:,3:]>0);b=np.clip(np.rint(b*255),0,255).astype('uint8');b[yy<=53]=source[yy<=53];b[yy>=121]=source[yy>=121];target=np.array(Image.open(R/a['rows'][i]['path']).convert('RGBA'));rows.append({'slot':i,'alphaExact':bool(np.array_equal(b[:,:,3],target[:,:,3])),'alphaMAE':float(np.abs(b[:,:,3].astype(float)-target[:,:,3]).mean()),'rgbaMAE':float(np.abs(b.astype(float)-target.astype(float)).mean()),'headFeetExact':bool(np.array_equal(target[:54],source[:54]) and np.array_equal(target[121:],source[121:]))})
q={'scope':'Reconstruction of accepted chest-only motion recipe against current selected East idle, no output frames or normal change. Palette differences may reflect downstream grading; alpha isolates motion.','recipeSource':'tools/build_bill_west_idle.py','rows':rows,'alphaExactCount':sum(r['alphaExact'] for r in rows),'headFeetExactCount':sum(r['headFeetExact'] for r in rows),'maxAlphaMAE':max(r['alphaMAE'] for r in rows),'maxRgbaMAE':max(r['rgbaMAE'] for r in rows)};(P/'motion-recipe-diagnosis.json').write_text(json.dumps(q,indent=2)+'\n');print(json.dumps({k:v for k,v in q.items() if k!='rows'}))
